<?php
declare(strict_types=1);
require __DIR__.'/../app/BusinessSubscriptionChoice.php';
$p=new PDO('sqlite::memory:');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$p->exec('CREATE TABLE subscription_plans(code TEXT PRIMARY KEY,is_active INT);CREATE TABLE subscription_plan_prices(plan_code TEXT,billing_frequency TEXT,amount NUMERIC,currency TEXT,PRIMARY KEY(plan_code,billing_frequency));CREATE TABLE business_subscriptions(id INT,quoted_amount NUMERIC);CREATE TABLE business_account_applications(id INT,business_details_json TEXT);');
foreach(['featured'=>49900,'page'=>69900,'page_premium'=>119900,'basic'=>19900] as $code=>$amount){$p->prepare('INSERT INTO subscription_plans VALUES(?,1)')->execute([$code]);$p->prepare('INSERT INTO subscription_plan_prices VALUES(?,"monthly",?,"COP")')->execute([$code,$amount]);}
$p->exec('INSERT INTO subscription_plan_prices VALUES("basic","quarterly",777,"COP"),("featured","annual",1,"COP");INSERT INTO business_subscriptions VALUES(1,12345);INSERT INTO business_account_applications VALUES(1,\'{"requested_subscription":{"quoted_amount":"222.00"}}\')');
$sql=file_get_contents(__DIR__.'/../database/migrations/037-subscription-pricing-policy.sqlite.sql');$p->exec($sql);$s=new BusinessSubscriptionChoice($p);$checks=0;function ck(bool $v,string $m):void{global $checks;if(!$v)throw new RuntimeException($m);$checks++;}
$expected=['featured'=>[124750,259480,499000],'page'=>[174750,363480,699000],'page_premium'=>[299750,623480,1199000]];
foreach($expected as $plan=>$amounts)foreach(array_combine(['quarterly','semiannual','annual'],$amounts) as $period=>$total){$q=$s->quote($plan,$period);ck($q['quoted_amount']===number_format($total,2,'.','')&&$q['quote_status']==='quoted','Exact total '.$plan.' '.$period);}
ck((float)$p->query('SELECT amount FROM subscription_plan_prices WHERE plan_code="basic" AND billing_frequency="quarterly"')->fetchColumn()===777.0,'Legacy basic untouched');ck((float)$p->query('SELECT quoted_amount FROM business_subscriptions')->fetchColumn()===12345.0,'Subscription quote immutable');ck(str_contains($p->query('SELECT business_details_json FROM business_account_applications')->fetchColumn(),'222.00'),'Application quote immutable');
$p->exec($sql);ck((int)$p->query('SELECT COUNT(*) FROM subscription_pricing_policy')->fetchColumn()===4,'Reapply idempotent');
foreach([['weekly',1],['quarterly',0],['monthly',2],['annual',13]] as [$period,$months]){$rejected=false;try{$p->prepare('INSERT OR REPLACE INTO subscription_pricing_policy VALUES(?,?)')->execute([$period,$months]);}catch(PDOException){$rejected=true;}ck($rejected,'Policy check rejects invalid input');}
$p->exec('DELETE FROM subscription_plan_prices WHERE plan_code="page";INSERT INTO subscription_plan_prices VALUES("page","monthly",69900,"USD");');$p->exec($sql);ck((int)$p->query('SELECT COUNT(*) FROM subscription_plan_prices WHERE plan_code="page" AND billing_frequency<>"monthly"')->fetchColumn()===0,'No COP calculation from another currency');
$p->exec('UPDATE subscription_plan_prices SET amount=NULL WHERE plan_code="page_premium" AND billing_frequency="monthly";DELETE FROM subscription_plan_prices WHERE plan_code="page_premium" AND billing_frequency<>"monthly";');$p->exec($sql);ck((int)$p->query('SELECT COUNT(*) FROM subscription_plan_prices WHERE plan_code="page_premium" AND billing_frequency<>"monthly"')->fetchColumn()===0,'No multiplication from undefined monthly');
echo "OK $checks pricing policy checks\n";
